\set ON_ERROR_STOP on
SET client_encoding = 'UTF8';
SET standard_conforming_strings = off;

SET escape_string_warning = off;

-- Converted from ../knowledge_base_v1.sql for PostgreSQL 17.
-- 个人知识库第一阶段增量脚本
-- 适用: MySQL 8.0 / h_boot
-- 中文模糊搜索首期由应用生成二元词组并使用字段加权 LIKE；FULLTEXT 索引保留作后续优化。

CREATE TABLE IF NOT EXISTS "kb_space" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "name" varchar(100) NOT NULL,
  "owner_id" bigint NOT NULL,
  "status" smallint NOT NULL DEFAULT 1,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "kb_space_uk_kb_space_owner" ON "kb_space" ("owner_id");

-- Skipped MySQL ngram FULLTEXT index ft_kb_article_title; the application uses weighted LIKE search.
-- Skipped MySQL ngram FULLTEXT index ft_kb_article_keywords; the application uses weighted LIKE search.
-- Skipped MySQL ngram FULLTEXT index ft_kb_article_summary; the application uses weighted LIKE search.
-- Skipped MySQL ngram FULLTEXT index ft_kb_article_content; the application uses weighted LIKE search.
CREATE TABLE IF NOT EXISTS "kb_article" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "space_id" bigint NOT NULL,
  "owner_id" bigint NOT NULL,
  "title" varchar(200) NOT NULL,
  "keywords" varchar(1000) NULL,
  "summary" varchar(2000) NULL,
  "content" text NOT NULL,
  "search_content" text NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'DRAFT',
  "source_type" varchar(30) NOT NULL DEFAULT 'MANUAL',
  "source_file_id" bigint NULL,
  "current_version_id" bigint NULL,
  "publish_time" timestamp NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" smallint NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "kb_article_idx_kb_article_space_status" ON "kb_article" ("space_id", "status", "deleted", "update_time");
CREATE INDEX IF NOT EXISTS "kb_article_idx_kb_article_owner" ON "kb_article" ("owner_id", "deleted");

CREATE TABLE IF NOT EXISTS "kb_article_version" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "article_id" bigint NOT NULL,
  "version_no" int NOT NULL,
  "title" varchar(200) NOT NULL,
  "keywords" varchar(1000) NULL,
  "summary" varchar(2000) NULL,
  "content" text NOT NULL,
  "content_hash" char(64) NOT NULL,
  "source" varchar(30) NOT NULL DEFAULT 'USER_EDIT',
  "created_by" bigint NOT NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "kb_article_version_uk_kb_article_version" ON "kb_article_version" ("article_id", "version_no");
CREATE INDEX IF NOT EXISTS "kb_article_version_idx_kb_article_version_time" ON "kb_article_version" ("article_id", "create_time");

CREATE TABLE IF NOT EXISTS "kb_source_file" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "space_id" bigint NOT NULL,
  "owner_id" bigint NOT NULL,
  "sys_file_id" bigint NOT NULL,
  "article_id" bigint NULL,
  "file_name" varchar(255) NOT NULL,
  "file_ext" varchar(20) NOT NULL,
  "content_type" varchar(150) NULL,
  "file_size" bigint NOT NULL,
  "parsed_text" text NULL,
  "status" varchar(30) NOT NULL DEFAULT 'UPLOADED',
  "error_message" varchar(2000) NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "kb_source_file_idx_kb_source_owner" ON "kb_source_file" ("owner_id", "status", "create_time");
CREATE INDEX IF NOT EXISTS "kb_source_file_idx_kb_source_article" ON "kb_source_file" ("article_id");
CREATE INDEX IF NOT EXISTS "kb_source_file_idx_kb_source_sys_file" ON "kb_source_file" ("sys_file_id");

CREATE TABLE IF NOT EXISTS "kb_import_task" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "source_file_id" bigint NOT NULL,
  "owner_id" bigint NOT NULL,
  "article_id" bigint NULL,
  "status" varchar(30) NOT NULL DEFAULT 'PENDING',
  "progress" int NOT NULL DEFAULT 0,
  "current_stage" varchar(100) NULL,
  "retry_count" int NOT NULL DEFAULT 0,
  "error_message" varchar(2000) NULL,
  "model" varchar(100) NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "kb_import_task_idx_kb_import_owner" ON "kb_import_task" ("owner_id", "status", "create_time");
CREATE INDEX IF NOT EXISTS "kb_import_task_idx_kb_import_source" ON "kb_import_task" ("source_file_id", "create_time");

CREATE TABLE IF NOT EXISTS "kb_article_annotation" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "article_id" bigint NOT NULL,
  "article_version_id" bigint NOT NULL,
  "author_id" bigint NOT NULL,
  "source_type" varchar(20) NOT NULL DEFAULT 'MANUAL',
  "content" text NOT NULL,
  "quoted_text" text NULL,
  "qa_selected_text" text NULL,
  "anchor_type" varchar(20) NOT NULL DEFAULT 'ARTICLE',
  "anchor_start" int NULL,
  "anchor_end" int NULL,
  "anchor_block_id" varchar(100) NULL,
  "qa_message_id" bigint NULL,
  "pinned" smallint NOT NULL DEFAULT 0,
  "status" smallint NOT NULL DEFAULT 1,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "kb_article_annotation_idx_kb_annotation_article" ON "kb_article_annotation" ("article_id", "article_version_id", "status", "pinned", "create_time");
CREATE INDEX IF NOT EXISTS "kb_article_annotation_idx_kb_annotation_author" ON "kb_article_annotation" ("author_id", "status");
CREATE INDEX IF NOT EXISTS "kb_article_annotation_idx_kb_annotation_qa" ON "kb_article_annotation" ("qa_message_id");

CREATE TABLE IF NOT EXISTS "kb_qa_session" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "article_id" bigint NOT NULL,
  "user_id" bigint NOT NULL,
  "title" varchar(200) NULL,
  "status" smallint NOT NULL DEFAULT 1,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "kb_qa_session_idx_kb_qa_session_user" ON "kb_qa_session" ("user_id", "article_id", "status", "update_time");

CREATE TABLE IF NOT EXISTS "kb_qa_message" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "session_id" bigint NOT NULL,
  "role" varchar(20) NOT NULL,
  "content" text NOT NULL,
  "quoted_text" text NULL,
  "model" varchar(100) NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "kb_qa_message_idx_kb_qa_message_session" ON "kb_qa_message" ("session_id", "create_time", "id");

INSERT INTO "sys_menu"
  ("parent_id", "name", "path", "component", "type", "permission", "icon", "sort", "status", "create_time", "update_time")
SELECT 0, '知识库', '/knowledge', 'knowledge/index', 1, 'knowledge:article:list', 'Reading', 3, 1, NOW(), NOW()
WHERE NOT EXISTS (SELECT 1 FROM "sys_menu" WHERE "path" = '/knowledge');

INSERT INTO "sys_role_menu" ("role_id", "menu_id")
SELECT 1, m.id FROM "sys_menu" m
WHERE m.path = '/knowledge'
  AND NOT EXISTS (
    SELECT 1 FROM "sys_role_menu" rm WHERE rm.role_id = 1 AND rm.menu_id = m.id
  );

-- 兼容已执行过旧版脚本的数据库。
ALTER TABLE "kb_qa_message" ADD COLUMN IF NOT EXISTS "quoted_text" text NULL;
